    public function up(): void
    {
        try {
            $this->apply();
        } catch (\Throwable $e) {
            Log::error('[dailyvocab-fix] aborted, nothing was changed: ' . $e->getMessage());
        }
    }

    private function apply(): void
    {
        foreach (['book_items', 'book_chapters'] as $t) {
            if (!Schema::hasTable($t)) { return; }
        }
        if (Schema::hasTable(self::BACKUP)) { Log::info('[dailyvocab-fix] already applied'); return; }

        $data = $this->data();
        $skipped = 0;
        $detailsPlan = [];   // item id => [old, new]
        $colPlan = [];       // [table, id, col, old, new]

        // 1. text edits inside the lesson body
        foreach ($data['pairs'] as $itemId => $pairs) {
            $row = DB::table('book_items')->where('id', (int) $itemId)->first(['id', 'details']);
            if (!$row || $row->details === null) { $skipped += count($pairs); continue; }
            $d = $row->details;
            foreach ($pairs as [$old, $new]) {
                if (substr_count($d, $old) === 1) {
                    $d = str_replace($old, $new, $d);
                } else {
                    $skipped++;
                }
            }
            if ($d !== $row->details) {
                $detailsPlan[(int) $itemId] = [$row->details, $d];
            }
        }

        // 2. whole-body replacements (lists that were rebuilt)
        foreach ($data['replace'] as $itemId => $r) {
            $row = DB::table('book_items')->where('id', (int) $itemId)->first(['id', 'details']);
            if (!$row || $row->details === null || sha1($row->details) !== $r['old_sha1']) { $skipped++; continue; }
            $detailsPlan[(int) $itemId] = [$row->details, $r['new']];
        }

        // 3. title / short_details / keyword
        foreach ($data['fields'] as [$itemId, $col, $old, $new]) {
            if (!in_array($col, ['title', 'short_details', 'keyword', 'sub_title'], true)) { $skipped++; continue; }
            $cur = DB::table('book_items')->where('id', (int) $itemId)->value($col);
            if ($cur === null || (string) $cur !== (string) $old) { $skipped++; continue; }
            $colPlan[] = ['book_items', (int) $itemId, $col, $old, $new];
        }

        // 4. chapter titles
        foreach ($data['chapters'] as [$cid, $old, $new]) {
            $cur = DB::table('book_chapters')->where('id', (int) $cid)->value('title');
            if ($cur === null || (string) $cur !== (string) $old) { $skipped++; continue; }
            $colPlan[] = ['book_chapters', (int) $cid, 'title', $old, $new];
        }

        if (!$detailsPlan && !$colPlan) { Log::info('[dailyvocab-fix] nothing to change (skipped ' . $skipped . ')'); return; }

        Schema::create(self::BACKUP, function ($t) {
            $t->id();
            $t->string('tbl', 20);
            $t->unsignedBigInteger('ref_id');
            $t->string('col', 20);
            $t->longText('old_value')->nullable();
        });

        try {
            DB::transaction(function () use ($detailsPlan, $colPlan) {
                $now = now();
                foreach ($detailsPlan as $id => [$old, $new]) {
                    DB::table(self::BACKUP)->insert(['tbl' => 'book_items', 'ref_id' => $id, 'col' => 'details', 'old_value' => $old]);
                    $n = DB::table('book_items')->where('id', $id)->where('details', $old)->update(['details' => $new, 'updated_at' => $now]);
                    if ($n !== 1) { throw new \RuntimeException("book_items {$id}.details changed concurrently"); }
                }
                foreach ($colPlan as [$table, $id, $col, $old, $new]) {
                    DB::table(self::BACKUP)->insert(['tbl' => $table, 'ref_id' => $id, 'col' => $col, 'old_value' => $old]);
                    $n = DB::table($table)->where('id', $id)->where($col, $old)->update([$col => $new, 'updated_at' => $now]);
                    if ($n !== 1) { throw new \RuntimeException("{$table} {$id}.{$col} changed concurrently"); }
                }
            });
        } catch (\Throwable $e) {
            Schema::dropIfExists(self::BACKUP);
            throw $e;
        }

        Log::info('[dailyvocab-fix] lesson bodies changed: ' . count($detailsPlan) . ', title/summary fields changed: ' . count($colPlan) . ', skipped (no longer matches): ' . $skipped);
    }

    public function down(): void
    {
        if (!Schema::hasTable(self::BACKUP)) { return; }
        DB::transaction(function () {
            foreach (DB::table(self::BACKUP)->get() as $r) {
                DB::table($r->tbl)->where('id', $r->ref_id)->update([$r->col => $r->old_value]);
            }
        });
        Schema::dropIfExists(self::BACKUP);
    }
